use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

const MAX_TOOL_ROUNDS: u32 = 4;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let system =
            "You are a customer support assistant. If you need information from the \
             knowledge base, call the `lookup` tool with a search query; otherwise answer \
             directly.";

        let mut prompt = format!(
            "Question: {}\nKnowledge so far: {}",
            ctx.question,
            ctx.knowledge.join("; ")
        );

        let mut rounds = 0;
        loop {
            rounds += 1;
            if rounds > MAX_TOOL_ROUNDS {
                return ResponseResult::Error(LlmError {
                    message: "exceeded maximum tool-call rounds".to_string(),
                });
            }

            match tool_llm::generate(system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool != "lookup" {
                        return ResponseResult::Error(LlmError {
                            message: format!("unsupported tool requested: {}", req.tool),
                        });
                    }

                    let results = kb_read::lookup(&req.query);
                    prompt = format!(
                        "{}\nTool lookup(\"{}\") results: {}",
                        prompt,
                        req.query,
                        results.join("; ")
                    );
                }
            }
        }
    }
}

export!(Node);
